using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEngine;

// Continuous physical day: no position changes, account injection, or disabled ambient traffic.
public sealed class OneDayTrafficDriveTest:MonoBehaviour {
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-oneDayTrafficTest")>=0)new GameObject("Continuous day traffic validation").AddComponent<OneDayTrafficDriveTest>();}
 DriveSession s;LiveTrafficValidationTest driver;bool ok=true,halt;float startReal,nextSample;readonly StringBuilder report=new StringBuilder();int meals,sleeps,fills,rides;float npcStart;
 void Log(string text){report.AppendLine(text);Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/one-day-traffic-drive.txt",report.ToString());}
 void Check(bool pass,string text){ok&=pass;Log((pass?"PASS ":"FAIL ")+text);}
 float NpcDistance(){float d=0;foreach(var c in s.traffic.cars)d+=c.totalTravel;return d;}
 void Update(){if(!s)return;var choice=s.GetComponent<ScenarioChoiceSituation>();if(choice&&choice.Open){Log("CHOICE "+choice.Course.id+" wait/observe");choice.Select(0);Time.timeScale=4;}if(s.requests&&!s.requests.request.Resolved)s.requests.request.DeferSafety();
  if(Time.realtimeSinceStartup>=nextSample){nextSample=Time.realtimeSinceStartup+10;var l=s.business.ledger;Log("SAMPLE elapsed="+l.Elapsed.ToString("F1")+" metres="+l.Metres.ToString("F1")+" rides="+rides+" cash="+l.Account.Cash+" net="+l.ProjectedNet+" fuel="+l.Account.Fuel.ToString("F1")+" satiety="+l.Driver.satiety.ToString("F1")+" fatigue="+l.Driver.fatigue.ToString("F1")+" npc="+NpcDistance().ToString("F0")+" pos="+s.taxi.transform.position+" trip="+s.jobs.trip.State);}
  if(Time.realtimeSinceStartup-startReal>1200){Check(false,"real-time watchdog");Finish();}}
 IEnumerator Leg(string name){Log("LEG "+name+" at="+s.business.ledger.Elapsed.ToString("F1"));yield return driver.Drive(name);Check(driver.Passed,"physical safety checks "+name);if(!driver.Arrived){Check(false,"blocked leg "+name);halt=true;}else Log("ARRIVED "+name+" at="+s.business.ledger.Elapsed.ToString("F1"));}
 IEnumerator Ride(string preferred=null){var jobs=s.jobs;var zones=s.GetComponent<ServiceLawZones>();jobs.Generate();int chosen=-1;float best=float.MaxValue;
  if(preferred!=null){var course=zones.scenarios.Find(x=>x.id==preferred);var offer=new JobOffer();if(zones.ConfigureScenario(offer,course)){offer.fare=3000+Mathf.CeilToInt(offer.distance*4/100)*100;offer.seconds=Mathf.Max(120,Mathf.Ceil(offer.distance/4+90+offer.waitSeconds));offer.requiredScore=70;jobs.offers[0]=offer;chosen=0;}}
  if(chosen<0)for(int i=0;i<jobs.offers.Length;i++){var offer=jobs.offers[i];if(offer==null)continue;float at;int edge=jobs.nav.hd.Nearest(s.taxi.transform.position,s.taxi.transform.forward,out at);var stop=jobs.stops[offer.pickup];var r=jobs.nav.hd.Route(edge,at,stop.laneEdge,stop.laneAt);float length=(r==null?float.MaxValue:r.path.length)+offer.distance;if(length<best){best=length;chosen=i;}}
  Check(chosen>=0&&jobs.Accept(chosen),"accept "+preferred);if(jobs.trip.State!=TripState.ToPickup){halt=true;yield break;}Log("OFFER "+jobs.current.scenarioId+" pickup="+jobs.current.pickup+" drop="+jobs.current.drop+" distance="+jobs.current.distance+" fare="+jobs.current.fare);
  yield return Leg("pickup");if(halt)yield break;Check(jobs.Interact()&&jobs.trip.State==TripState.OnTrip,"physical curb boarding");if(jobs.trip.State!=TripState.OnTrip){halt=true;yield break;}
  Check(jobs.nav.RequiredVia<0,"no situation waypoint");yield return Leg("delivery");if(halt)yield break;int before=s.business.ledger.Income;Check(jobs.Interact()&&jobs.trip.State==TripState.Complete,"physical curb dropoff");if(jobs.trip.State!=TripState.Complete){halt=true;yield break;}rides++;Log("FARE paid="+(s.business.ledger.Income-before)+" manner="+s.manners.ledger.Score+" scenarioCompleted="+zones.Completed);yield return new WaitForSecondsRealtime(1.1f);
 }
 IEnumerator Service(int kind){var stop=s.jobs.stops[s.services.indices[kind==3?2:kind]];s.jobs.nav.SetDestination(stop);yield return Leg(kind==1?"meal approach":"sleep approach");if(halt)yield break;s.services.Toggle();Check(s.services.RequestAction(kind)&&s.services.ConfirmAction(true),"service "+kind);if(s.services.open)s.services.Toggle();if(kind==1)meals++;else sleeps++;Time.timeScale=4;}
 IEnumerator Fuel(){var stations=s.services.Stations;int selected=-1;float best=float.MaxValue,at;var hd=s.jobs.nav.hd;int edge=hd.Nearest(s.taxi.transform.position,s.taxi.transform.forward,out at);for(int i=0;i<stations.Count;i++){var a=stations[i].approach;var r=hd.Route(edge,at,a.laneEdge,a.laneAt);if(r!=null&&r.path.length<best){best=r.path.length;selected=i;}}Check(selected>=0,"reachable fuel station");if(selected<0){halt=true;yield break;}var station=stations[selected];s.jobs.nav.SetDestination(station.approach);yield return Leg("fuel approach "+station.id);if(halt)yield break;
  var probe=gameObject.AddComponent<FuelStationProbe>();probe.externallyDriven=true;probe.session=s;var first=new List<Vector3>{s.taxi.transform.position};for(int i=0;i<25;i++)first.Add(station.drivePath[i]);first.Add(station.pump);yield return probe.Drive(first,"continuous fuel entry");Check(probe.Passed,"fuel entry safety");if(!probe.Passed){halt=true;yield break;}Check(s.services.FuelAtPump==selected,"physical pump reached");if(s.services.FuelAtPump!=selected){halt=true;yield break;}s.services.Toggle();Check(s.services.Buy(0),"ten percent fuel purchase");fills++;if(s.services.open)s.services.Toggle();Time.timeScale=4;
  var second=new List<Vector3>{station.pump};for(int i=26;i<station.drivePath.Length;i++)second.Add(station.drivePath[i]);second.Add(hd.paths[station.approach.laneEdge].Position(station.approach.laneAt+63));yield return probe.Drive(second,"continuous fuel exit");Check(probe.Passed,"fuel exit safety");if(!probe.Passed)halt=true;Destroy(probe);}
 IEnumerator Start(){yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();startReal=Time.realtimeSinceStartup;var b=s.business;Check(b.ledger.OneDay&&b.ledger.Settings.daySeconds==1200,"real 1200-second day");Check(s.traffic.cars.Count>=48,"48 ambient cars retained");npcStart=NpcDistance();s.taxi.automated=true;s.taxi.autoBrake=true;s.assisted.allowAutomated=true;driver=gameObject.AddComponent<LiveTrafficValidationTest>();driver.externallyDriven=true;driver.session=s;driver.cruise=8;driver.legTimeout=600;b.Depart();Time.timeScale=4;Log("START default spawn="+s.taxi.transform.position+" one continuous run; x4 simulation, physical fixed step unchanged");
  yield return Ride();if(halt){Finish();yield break;}yield return Service(1);if(halt){Finish();yield break;}yield return Fuel();if(halt){Finish();yield break;}yield return Service(3);if(halt){Finish();yield break;}
  while(b.ledger.CanAccept&&b.ledger.SecondsLeft>180&&rides<5){yield return Ride();if(halt){Finish();yield break;}}
  s.taxi.autoThrottle=0;s.taxi.autoBrake=true;while(!b.ShowingSummary){if(s.jobs.trip.State==TripState.OnTrip){Check(false,"unexpected passenger at idle");break;}yield return null;}Check(b.ShowingSummary,"day settles on actual clock");Check(meals>0&&sleeps>0&&fills>0&&rides>0,"transport meal sleep fuel all exercised");Check(NpcDistance()>npcStart+1000,"aggregate ambient travel increased");Check(b.SaveCheckpoint(),"day result saved");Finish();
 }
 void Finish(){var l=s.business.ledger;Log("RESULT success="+ok+" elapsed="+l.Elapsed+" metres="+l.Metres+" rides="+rides+" income="+l.Income+" net="+l.ProjectedNet+" meals="+meals+" sleep="+sleeps+" refills="+fills+" fuel="+l.Account.Fuel+" collision="+s.manners.collisionEvents+" red="+s.manners.redEvents+" brakes="+s.manners.brakeEvents);foreach(var e in s.law.ledger.Events)Log("LAW "+e.family+" "+e.scenario+" "+e.junction+" deduction="+e.Deduction+" "+e.reason);Application.Quit(ok?0:1);}
}
